#include <iostream>
#include <cstdio>
#include <iomanip>

int main() {
    int num = 1427;
    double val = 1427.0;

    // C-style printf with # and 0 flags
    std::printf("%#o\n", num);
    std::printf("%#x\n", num);
    std::printf("%#X\n", num);
    std::printf("%g\n", val);
    std::printf("%#g\n", val);
    std::printf("%+09d\n", 452);
    std::printf("%09d\n", 452);

    // C++ modern equivalent using iostreams
    std::cout << "\"Escape Test\"\tBackslash: \\\n";
    return 0;
}

#include <cstdio>

int main() {
    int a = 0, b = 0, c = 0, d = 0, e = 0, f = 0, g = 0;
    int count_read = 0;

    // Input contains: -70 -70 070 0x70 70 70 70
    // %d parses -70 as decimal (-70)
    // %i parses -70 as decimal (-70)
    // %i parses 070 as octal (56 decimal)
    // %i parses 0x70 as hexadecimal (112 decimal)
    // %o parses 70 as octal (56 decimal)
    // %u parses 70 as unsigned decimal (70)
    // %x parses 70 as hexadecimal (112 decimal)
    int matched = std::scanf("%d%i%i%i%o%u%x%n", &a, &b, &c, &d, &e, &f, &g, &count_read);

    if (matched == 7) {
        std::printf("Matched: %d items (%d chars read)\n", matched, count_read);
        std::printf("%d %d %d %d %d %d %d\n", a, b, c, d, e, f, g);
    }
    return 0;
}
